const products = [
  {id:1,name:'Wind-Up Penguin',category:'Toys',price:1575,tag:'bestseller',image:'data:image/jpeg;base64,',desc:'Our most-loved toy — wobbles and waddles across the floor, safe ABS build, ages 3+.'},
  {id:2,name:'Angry Birds Light-Up Toy',category:'Toys',price:2400,tag:null,image:'data:image/jpeg;base64,',desc:'Panorama lighting, no batteries needed.'},
  {id:3,name:'Thomas the Train',category:'Toys',price:2400,tag:null,image:'data:image/jpeg;base64,',desc:'Classic wind-up engine, easy for little hands.'},
  {id:4,name:'Wind-Up Cow',category:'Toys',price:1950,tag:null,image:'data:image/jpeg;base64,',desc:'Safe ABS material, easy wind-up mechanism.'},
  {id:5,name:'Wind-Up Duck',category:'Toys',price:1725,tag:'new',image:'data:image/jpeg;base64,',desc:'Wobbles and rolls, builds motor skills through play.'},
  {id:6,name:'Rechargeable Water Dispenser',category:'Kitchen & Home',price:6000,tag:'bestseller',image:'data:image/jpeg;base64,',desc:'One-touch pouring — no more tilting heavy bottles. USB rechargeable.'},
  {id:7,name:'Instant Ice Cream Roll Maker',category:'Kitchen & Home',price:3750,tag:null,image:'data:image/jpeg;base64,',desc:'Comes with two spatulas — rolls ready in minutes.'},
  {id:8,name:'Soap-Dispensing Dish Brush',category:'Kitchen & Home',price:2850,tag:'new',image:'data:image/jpeg;base64,',desc:'Refillable handle for quick, mess-free scrubbing.'},
  {id:9,name:'2-in-1 Facial Trimmer',category:'Beauty & Personal Care',price:3600,tag:'bestseller',image:'data:image/jpeg;base64,',desc:'Painless, rechargeable, easy to use at home. For ladies.'}
];

let cart=[];
const money = n => n ? "Rs. " + n.toLocaleString("en-PK") : "Price on request";
const WA_NUMBER = "923161068217";

function badgeHTML(tag){
  if(tag === 'bestseller') return '<span class="badge badge-best">Best Seller</span>';
  if(tag === 'new') return '<span class="badge badge-new">New</span>';
  return '';
}

function card(p){
  const img = p.image ? `<img src="${p.image}" alt="${p.name}">` : (p.icon || '');
  return `<article class="product" onclick="openDetails(${p.id})">
    <div class="product-img">${badgeHTML(p.tag)}${img}</div>
    <h3>${p.name}</h3><p class="price">${money(p.price)}</p>
    <button class="add" onclick="event.stopPropagation();addToCart(${p.id})">🛒 Add to Cart</button>
  </article>`;
}

function render(){
  document.getElementById("productGrid").innerHTML=products.slice(0,6).map(card).join("");
  document.querySelectorAll(".category-products").forEach(el=>{
    const list=products.filter(p=>p.category===el.dataset.category);
    el.innerHTML=list.map(card).join("");
  });
}

function addToCart(id){
  const p=products.find(x=>x.id===id);
  cart.push(p);
  document.getElementById("cartCount").textContent=cart.length;
  renderCart();
  openDrawer('cartDrawer');
}

function renderCart(){
  document.getElementById("cartItems").innerHTML=cart.length?cart.map((p,i)=>`<div class="cart-row"><span>${p.name}</span><strong>${money(p.price)}</strong></div>`).join(""):"<p>Your cart is empty.</p>";
  document.getElementById("cartTotal").textContent=money(cart.reduce((s,p)=>s+(p.price||0),0));
}

function openDrawer(id){
  document.getElementById(id).classList.add('open');
  document.getElementById('overlay').classList.add('open');
}
function closeAll(){
  document.getElementById('cartDrawer').classList.remove('open');
  document.getElementById('detailModal').classList.remove('open');
  document.getElementById('overlay').classList.remove('open');
}

function openDetails(id){
  const p = products.find(x=>x.id===id);
  if(!p) return;
  const img = p.image ? `<img src="${p.image}" alt="${p.name}">` : `<div class="detail-icon">${p.icon||''}</div>`;
  const waText = encodeURIComponent('Hi BaranB, I want to order: ' + p.name + ' (' + money(p.price) + ')');
  document.getElementById('detailContent').innerHTML = `
    <div class="detail-img">${badgeHTML(p.tag)}${img}</div>
    <div class="detail-info">
      <h2>${p.name}</h2>
      <p class="detail-price">${money(p.price)}</p>
      <p class="detail-desc">${p.desc||''}</p>
      <a class="btn orange full" href="https://wa.me/${WA_NUMBER}?text=${waText}" target="_blank" rel="noopener">Order on WhatsApp</a>
    </div>`;
  openDrawer('detailModal');
}

document.getElementById("cartBtn").onclick=()=>{renderCart();openDrawer('cartDrawer');};
document.getElementById("closeCart").onclick=closeAll;
document.getElementById("closeDetail").onclick=closeAll;
document.getElementById("overlay").onclick=closeAll;

document.getElementById("cartOrderBtn").onclick=()=>{
  if(!cart.length) return;
  const linesTxt = cart.map(p=>'- '+p.name+' ('+money(p.price)+')').join('\n');
  const total = money(cart.reduce((s,p)=>s+(p.price||0),0));
  const msg = encodeURIComponent('Hi BaranB, I want to order:\n'+linesTxt+'\nTotal: '+total);
  window.open('https://wa.me/'+WA_NUMBER+'?text='+msg,'_blank');
};

document.getElementById("searchBtn").onclick=()=>{
  const q=document.getElementById("search").value.toLowerCase();
  const results=products.filter(p=>(p.name+" "+p.category).toLowerCase().includes(q));
  document.getElementById("productGrid").innerHTML=(q?results:products.slice(0,6)).map(card).join("");
  document.getElementById("products").scrollIntoView({behavior:"smooth"});
};

render();
